"""Derive SkyyBazaar/build_skyybazaar_0.1.11.py from the LIVE 0.1.10 (build_skyybazaar_0.1.10.py = the tools/deploy_set.py SET pin, GENERATED by
tools/bazaar_0_1_10_patch.py; 0.1.10 and every older script stay untouched).
Run:  python tools/bazaar_0_1_11_patch.py   then   python SkyyBazaar/build_skyybazaar_0.1.11.py   then   python SkyyBazaar/test_skyybazaar_0.1.11.py

0.1.11 (2026-10-14) = REBIRTH R4, the Bazaar side (research/cloud/Rebirth-Spec.md 2.1 / 2.4 / 4.3 / 6 R4; docs/answered/economy.md 2026-10-13
REBIRTH SPEC Q9, Skyy word for word: "all three. can auto close all if you click continue." -> a Continue button auto-closes all open
orders / listings (refund items + coins) before going on).
WHAT THERE IS TO CLOSE: nothing. SkyyBazaar 0.1.x is INSTANT buy / sell against the server market maker only - no buy orders, no sell
offers, no escrow, no claim stash (the order book is the docstring's "PLANNED 0.2"). Every trade finishes inside one Market lock on the
player's world thread, so between two trades a profile never has coins or items held by the Bazaar. So:
 A. bazaar:fn:closeall answers "ok:0" for every valid profile key (idempotent and crash-safe by construction: it writes no file and moves
    no coin or item; one CLOSEALL line in trades.log records the call).
 B. bazaar:fn:wouldclose answers "ok:0:0:0:0" (same shape as the Auction House's, so SkyyRebirth reads both the same way).
 C. Both are removed from the bridge at shutdown. Nothing else changes (no price, product, page, file or trade change).
WHEN THE ORDER BOOK IS BUILT (0.2) it must keep this exact contract and make closeall real: cancel every open order of the key, return
the UNFILLED escrow (coins of a buy order, items of a sell offer) through the planned claim stash with a journaled, one-atomic-write-per-
order step (the Auction House 0.1.5 closeAll0 pattern), and answer err:... while anything stays open.

KEY CONTRACT (for SkyyRebirth's Continue button - built in a later Rebirth round; java.lang types only, through skyy.bridge):
  bazaar:fn:closeall    java.util.function.Function. apply(String pkey) -> String. Never throws, never calls another mod back, any thread.
                        pkey = the profile key (profile:fn:key(uuid), or uuid.toString() without SkyyProfiles).
     "ok:<n>"             every open order of pkey is closed now; n = how many THIS call closed (always 0 in 0.1.x).
     "err:bad-key"        pkey null / empty / not a String.
     "err:<reason>"       (0.2+) anything left open -> SkyyRebirth treats every err as "not done".
  bazaar:fn:wouldclose  java.util.function.Function. apply(String pkey) -> String, read-only:
     line 1  "ok:<closable>:<blocking>:<claims>:<coins>"  (0.1.x: always ok:0:0:0:0), then one line per open order (none in 0.1.x):
             "<id>\t<1 closable | 0 blocking>\t<qty>\t<unit price>\t<created millis>\t<item name>"
  SkyyRebirth reads wouldclose for the page lines, calls closeall on Continue, then re-reads wouldclose: only "ok:0:0:..." means the
  Bazaar check is met. Q15 "Allow it (Recommended)": buying Bazaar goods with coins before a rebirth stays allowed.
Rolling back to 0.1.10 is safe (no data change). Classes changed: + BzRebirthFn; SkyyBazaarPlugin.setup / shutdown (publish / remove the
two keys); CfgFn / CfgRows (version text only).
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HERE = os.path.join(ROOT, "SkyyBazaar")
src = os.path.join(HERE, "build_skyybazaar_0.1.10.py")
dst = os.path.join(HERE, "build_skyybazaar_0.1.11.py")
raw = open(src, "rb").read()
NL = "\r\n" if b"\r\n" in raw else "\n"
assert NL == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in 0.1.10"
s = raw.decode("utf8").replace("\r\n", "\n")
OLD = s
LF = "\n"
assert 'VERSION = "0.1.10"' in s and "BzRebirthFn" not in s, "not the live generated 0.1.10"


def rep(old, new, count=1):
    global s
    assert old in s, "anchor missing: " + old[:90]
    assert s.count(old) == count, "anchor count %d != %d: %s" % (s.count(old), count, old[:90])
    s = s.replace(old, new)


GONE_OK = set()


def gone(*lines):
    for ln in lines:
        GONE_OK.add(ln)


# ---------------------------------------------------------------------------------------------------------------- header + version
rep('''"""SkyyBazaar 0.1.10 - build script (javassist via jpype). Hypixel-Bazaar-style commodity market, MVP = INSTANT buy/sell against a
server market maker.
Run:   python build_skyybazaar_0.1.10.py           -> SkyyBazaar/SkyyBazaar-0.1.10.jar  (build only; deploys go through
       tools/deploy_set.py --yes, never --deploy)
       (0.1.10 is GENERATED from build_skyybazaar_0.1.9.py by tools/bazaar_0_1_10_patch.py - edit the patch, not this file; 0.1.9 came
''', '''"""SkyyBazaar 0.1.11 - build script (javassist via jpype). Hypixel-Bazaar-style commodity market, MVP = INSTANT buy/sell against a
server market maker.
Run:   python build_skyybazaar_0.1.11.py           -> SkyyBazaar/SkyyBazaar-0.1.11.jar  (build only; deploys go through
       tools/deploy_set.py --yes, never --deploy)
       (0.1.11 is GENERATED from build_skyybazaar_0.1.10.py by tools/bazaar_0_1_11_patch.py - edit the patch, not this file; 0.1.10 came
       from 0.1.9 by tools/bazaar_0_1_10_patch.py; 0.1.9 came
''')
gone('"""SkyyBazaar 0.1.10 - build script (javassist via jpype). Hypixel-Bazaar-style commodity market, MVP = INSTANT buy/sell against a',
     "Run:   python build_skyybazaar_0.1.10.py           -> SkyyBazaar/SkyyBazaar-0.1.10.jar  (build only; deploys go through",
     "       (0.1.10 is GENERATED from build_skyybazaar_0.1.9.py by tools/bazaar_0_1_10_patch.py - edit the patch, not this file; 0.1.9 came")
rep('''0.1.10 (2026-10-13) = THE ENCHANTED MATERIALS ARE PRODUCTS''', '''0.1.11 (2026-10-14) = REBIRTH R4 (research/cloud/Rebirth-Spec.md 2.4 / 4.3; KEY CONTRACT + notes: tools/bazaar_0_1_11_patch.py):
bazaar:fn:closeall (Function(String pkey) -> "ok:0": 0.1.x has instant trades only - no orders, no escrow, nothing a rebirth could
strand) + bazaar:fn:wouldclose (read-only, "ok:0:0:0:0"); both removed at shutdown. No price / product / page / file / trade change.

0.1.10 (2026-10-13) = THE ENCHANTED MATERIALS ARE PRODUCTS''')
rep('VERSION = "0.1.10"', 'VERSION = "0.1.11"')
gone('VERSION = "0.1.10"')

# ---------------------------------------------------------------------------------------------------------------- the Function class
rep('''pl   = pool.makeClass(PKG + ".SkyyBazaarPlugin", pool.get(JP))
''', '''pl   = pool.makeClass(PKG + ".SkyyBazaarPlugin", pool.get(JP))
rbf  = pool.makeClass(PKG + ".BzRebirthFn")    # 0.1.11: bazaar:fn:closeall (op 0) / bazaar:fn:wouldclose (op 1)
''')
rep('''# ================= plugin =================
pl.addField(''', '''# ================= 0.1.11 BzRebirthFn: rebirth R4 (KEY CONTRACT in tools/bazaar_0_1_11_patch.py). 0.1.x has no orders, no escrow and no
# claim stash (instant trades only), so nothing is ever open: closeall = "ok:0" (+ one trades.log line), wouldclose = "ok:0:0:0:0".
rbf.addInterface(pool.get("java.util.function.Function"))
rbf.addField(CtField.make("public int op;", rbf))
rbf.addConstructor(CtNewConstructor.make("public BzRebirthFn(int op) { this.op = op; }", rbf))
rbf.addMethod(CtNewMethod.make(jt(r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof String) || ((String) o).trim().length() == 0) return "err:bad-key";
    if (this.op == 1) return "ok:0:0:0:0";
    @PKG@.Market.log("CLOSEALL key=" + ((String) o).trim().replace(' ', '_') + " closed=0 (instant trades only - no open orders, nothing held)");
    return "ok:0";
  } catch (Throwable t) {
    @PKG@.BzUtil.warn("bazaar:fn:" + (this.op == 1 ? "wouldclose" : "closeall") + " failed: " + t);
    return "err:exception";
  }
}"""), rbf))

# ================= plugin =================
pl.addField(''')
rep('''  @PKG@.Market.publishAll();
  @PKG@.Catalog.flushIfDirty();
''', '''  @PKG@.Market.publishAll();
  @PKG@.BzUtil.bridge().put("bazaar:fn:closeall", new @PKG@.BzRebirthFn(0));     // 0.1.11 rebirth R4 (tools/bazaar_0_1_11_patch.py)
  @PKG@.BzUtil.bridge().put("bazaar:fn:wouldclose", new @PKG@.BzRebirthFn(1));
  @PKG@.Catalog.flushIfDirty();
''')
rep('''  try { @PKG@.Market.unpublishAll(); } catch (Throwable t) { }
''', '''  try { @PKG@.Market.unpublishAll(); } catch (Throwable t) { }
  try { @PKG@.BzUtil.bridge().remove("bazaar:fn:closeall"); @PKG@.BzUtil.bridge().remove("bazaar:fn:wouldclose"); } catch (Throwable t) { }
''')
rep('''ALL = (utl, coin, prod, cat_, mkt, inv_, bags, res, trd, page, fac, cmd, aprv, aprc, arlc, arsc, ainc, adm, tick, pl, cfgc)''',
    '''ALL = (utl, coin, prod, cat_, mkt, inv_, bags, res, trd, page, fac, cmd, aprv, aprc, arlc, arsc, ainc, adm, tick, rbf, pl, cfgc)''')
gone('''ALL = (utl, coin, prod, cat_, mkt, inv_, bags, res, trd, page, fac, cmd, aprv, aprc, arlc, arsc, ainc, adm, tick, pl, cfgc)''')

# ---------------------------------------------------------------------------------------------------------------- guards
assert s.index("public BzRebirthFn(int op)") < s.index("new @PKG@.BzRebirthFn(0)")
_gone = sorted(ln for ln in set(OLD.split(LF)) - set(s.split(LF)))
_bad = [ln for ln in _gone if ln not in GONE_OK]
assert not _bad, "0.1.10 lines lost by accident: %s" % _bad[:5]
assert not os.path.exists(dst), dst + " already exists - delete it first (it is generated)"
compile(s, dst, "exec")
open(dst, "w", encoding="utf8", newline="").write(s.replace(LF, NL))
print("wrote", dst, "(%d lines; 0.1.10 had %d)" % (s.count(LF), OLD.count(LF)))
